//! `levels/ffa_vector.lvl` (generated by `scripts/gen_vector_level.py`): VECTOR VECTOR. Pinned: three Y-up rings at the
//! design heights and radii, four ramps whose ends land on the rings they join, prisms / panels / floating cubes,
//! spawns standing on the outer ring and cubes on the inner ring, a singularity that pushes outward on its own clock
//! without changing anything about gravity, and 30 s of live play that stays finite and honest.

use std::f32::consts::{PI, TAU};
use std::time::Duration;

use shinobi_proto::intent::{ClientPacket, PlayerIntent, ViewState, PITCH_LEVEL};
use shinobi_proto::quant::{dq_yaw, q_yaw};
use shinobi_sim::character::{sync_body_colliders, Cfg, MoveState};
use shinobi_sim::level::{parse_level_file, LevelFile, ShapeKind};
use shinobi_sim::power::PowerKind;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::tick::Server;

const RINGS: [(f32, f32); 3] = [(30.0, 0.0), (24.0, 8.0), (18.0, 16.0)];

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_vector.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_vector.lvl: {e}"))
}

fn server(l: &LevelFile) -> Server {
    let mut s = Server::new(Cfg::default());
    l.level.apply_to_server(&mut s);
    s.set_level_features(l.features.clone());
    s.set_spawns(l.level.spawns.clone());
    s.world.queries.update(&s.world.colliders);
    s
}

/// Height of the first static surface straight below (x, y, z), within `max` m.
fn ground(s: &Server, x: f32, y: f32, z: f32, max: f32) -> Option<f32> {
    let ray = Ray::new(point![x, y, z], vector![0.0, -1.0, 0.0]);
    s.world.queries.cast_ray(&s.world.bodies, &s.world.colliders, &ray, max, true, QueryFilter::exclude_dynamic()).map(|(_, t)| y - t)
}

fn angle_diff(to: f32, from: f32) -> f32 {
    (to - from + PI).rem_euclid(TAU) - PI
}

#[test]
fn three_y_up_rings_ramps_cubes_prisms_panels_and_the_counts() {
    let l = load();
    let rings: Vec<_> = l.features.shapes.iter().filter(|s| s.kind == ShapeKind::Ring).collect();
    assert_eq!(rings.len(), 3);
    for (ring, (r, top)) in rings.iter().zip(RINGS) {
        assert!((ring.radius - r).abs() < 1e-4 && (ring.center[1] + ring.thickness / 2.0 - top).abs() < 1e-4, "ring r={r} top={top}");
        assert!((ring.extent - 2.5).abs() < 1e-4, "2.5 m wide");
    }
    assert_eq!(l.level.boxes.iter().filter(|b| b.rot_z != 0.0).count(), 4, "four ramps");
    assert_eq!(l.features.zones.iter().filter(|z| z.tag == "prism").count(), 8);
    assert_eq!(l.features.zones.iter().filter(|z| z.tag == "refraction_panel").count(), 4);
    assert_eq!(l.level.boxes.len(), 4 + 12 + 8 + 4);
    assert_eq!(l.level.spawns.len(), 10);
    assert_eq!(l.pickups.iter().filter(|p| p.kind == PowerKind::None).count(), 4);
    assert!(l.pickups.iter().all(|p| p.kind == PowerKind::None), "no weapon pedestals");
    assert!(l.level.boxes.iter().all(|b| b.hp == 0.0));
}

#[test]
fn spawns_stand_on_the_outer_ring_and_cubes_on_the_inner_ring() {
    let l = load();
    let s = server(&l);
    for sp in &l.level.spawns {
        let r = (sp[0] * sp[0] + sp[2] * sp[2]).sqrt();
        assert!((r - 30.0).abs() < 0.5, "spawn {sp:?} on the outer ring line");
        let g = ground(&s, sp[0], sp[1], sp[2], 3.0).unwrap_or_else(|| panic!("spawn {sp:?} floats"));
        assert!((sp[1] - 0.81 - g).abs() < 0.05, "spawn {sp:?} stands on y={g}");
    }
    for p in &l.pickups {
        let g = ground(&s, p.pos[0], p.pos[1], p.pos[2], 3.0).unwrap_or_else(|| panic!("cube {:?} floats", p.pos));
        assert!((g - 16.0).abs() < 0.05, "cube {:?} on the inner ring", p.pos);
    }
}

#[test]
fn every_ramp_end_meets_the_ring_it_joins() {
    let l = load();
    let s = server(&l);
    for b in l.level.boxes.iter().filter(|b| b.rot_z != 0.0) {
        let (sn, cs) = b.rot_z.sin_cos();
        for end in [-1.0f32, 1.0] {
            // the top-surface end point of the ramp
            let (u, v) = (end * b.half[0], b.half[1]);
            let (x, y) = (b.center[0] + u * cs - v * sn, b.center[1] + u * sn + v * cs);
            let r = (x * x + b.center[2] * b.center[2]).sqrt();
            let (ring_r, ring_top) = RINGS.iter().copied().find(|(rr, top)| (r - rr).abs() < 1.5 && (y - top).abs() < 0.3)
                .unwrap_or_else(|| panic!("ramp end ({x}, {y}, {}) is not on a ring", b.center[2]));
            let g = ground(&s, x + end * cs * 0.6, y + 1.0, b.center[2], 2.0).expect("a ring just past the ramp end");
            assert!((g - ring_top).abs() < 0.3, "ramp end on ring r={ring_r} top={ring_top}: ground {g}");
        }
        assert!(b.rot_z.abs() < 0.35, "ramp slope {} rad stays walkable", b.rot_z);
    }
}

#[test]
fn the_singularity_pulses_on_its_clock_and_pushes_outward_without_touching_gravity() {
    let l = load();
    let h = l.features.hazards.iter().find(|h| h.tag == "singularity").expect("a singularity");
    assert_eq!(h.damage, 0.0, "a push, not damage");
    let first = (0..h.period_ticks).find(|t| h.is_active(*t)).expect("a pulse");
    assert!(first >= 30 * 60, "no pulse in the opening (first at tick {first})");
    assert!(h.is_telegraph(first - 1));
    assert!(!h.is_active(first + 600) && h.is_active(first + 599), "10 s long");

    let mut s = server(&l);
    let start = [10.0, 16.81, 14.0];
    s.add_player(1, start);
    let body = s.players[0].ch.body;
    s.world.bodies[body].set_position(Isometry::translation(start[0], start[1], start[2]), true);
    sync_body_colliders(&mut s.world, body);
    s.world.queries.update(&s.world.colliders);
    let cfg = *s.cfg();
    let gravity = cfg.gravity;
    let mut pushes = 0;
    for tick in first..first + 600 {
        s.players[0].ch.vel = vector![0.0, 0.0, 0.0];
        s.players[0].ch.state = MoveState::Grounded;
        let before = s.players[0].ch.vel;
        s.level_features.end_tick(&s.world, &mut s.players, tick, &cfg, true);
        let v = s.players[0].ch.vel;
        if v != before {
            pushes += 1;
            let out = (v.x * start[0] + v.z * start[2]) / (start[0].hypot(start[2]) * v.x.hypot(v.z));
            assert!(out > 0.99, "pushed straight away from the centre: {v:?}");
            assert!(v.x.hypot(v.z) > 10.0 && v.y > 0.0);
            assert!(matches!(s.players[0].ch.state, MoveState::Airborne));
        }
    }
    assert_eq!(pushes, 20, "one shove every 0.5 s for the 10 s pulse");
    assert_eq!(s.cfg().gravity, gravity, "no gravity change");
    assert_eq!(s.level_features.hazard_contacts().len(), 0, "no damage");
}

#[test]
fn thirty_seconds_with_live_features_is_clean() {
    const TICKS: u32 = 30 * 60;
    let l = load();
    let mut s = server(&l);
    for i in 0..3u16 {
        s.add_player(i + 1, l.level.spawns[i as usize * 3]);
    }
    for t in 0..TICKS {
        let tick = s.tick;
        for id in 1..=3u16 {
            let p = s.players.iter().find(|p| p.id == id).unwrap();
            let pos = p.pos(&s.world);
            let want = (-pos[0]).atan2(-pos[2]);
            let step = angle_diff(want, dq_yaw(p.yaw)).clamp(-0.21, 0.21);
            let pkt = ClientPacket {
                ack_snapshot_tick: tick.saturating_sub(6).max(1),
                view: ViewState { from_tick: tick.saturating_sub(6).max(1), alpha: 0 },
                intents: vec![PlayerIntent { tick, move_z: 127, aim_yaw: q_yaw(dq_yaw(p.yaw) + step), aim_pitch: PITCH_LEVEL, ..Default::default() }],
                ..Default::default()
            };
            s.ingest(id, &pkt.encode().unwrap());
        }
        s.frame(Duration::from_nanos(16_666_667));
        for p in &s.players {
            let pos = p.pos(&s.world);
            assert!(pos.iter().all(|c| c.is_finite()) && pos[0].abs() < 60.0 && pos[2].abs() < 60.0, "tick {t}: player {} at {pos:?}", p.id);
            assert_eq!(p.guard.strikes, 0, "tick {t}: player {} collected a strike", p.id);
        }
    }
}
